SELECT e.id, e.user_id, e.company_id, c.name AS company_name, c.logo AS company_logo, e.type, e.title, e.difficulty, e.status, e.is_starred, e.content, e.last_reviewed_at, e.create_time, e.update_time FROM tb_entry e LEFT JOIN tb_company c ON e.company_id = c.id WHERE e.user_id = #{userId}
AND e.company_id = #{query.companyId}
AND e.type = #{query.type}
AND e.difficulty = #{query.difficulty}
AND e.status = #{query.status}
AND e.is_starred = #{query.isStarred}
AND (e.title LIKE CONCAT('%', #{query.keyword}, '%') OR e.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND JSON_CONTAINS(e.tags, JSON_QUOTE(#{query.tag}))
ORDER BY e.create_time DESC, e.id DESC

SELECT e.id, e.user_id, e.company_id, c.name AS company_name, c.logo AS company_logo, e.type, e.title, e.difficulty, e.status, e.is_starred, e.content, e.last_reviewed_at, e.create_time, e.update_time FROM tb_entry e LEFT JOIN tb_company c ON e.company_id = c.id WHERE e.user_id = #{userId}
AND e.company_id = #{companyId}
AND e.type = #{type}
ORDER BY RAND() LIMIT #{limit}
